export function renderCurrentHandoff(state) {
  const experiments = state.verification.sealedExperiments
    .map((item) => `- \`${item.id}\` seed ${item.seed}: **${item.status}** — ${item.summary}`)
    .join('\n')
  const residuals = state.knownResiduals
    .map(
      (item) =>
        `- \`${item.id}\`: **${item.status}** — ${item.note}${item.url === undefined ? '' : ` [Record](${item.url})`}`
    )
    .join('\n')
  const nextActions = state.nextActions.map((item, index) => `${index + 1}. ${item}`).join('\n')
  return `<!-- Generated by .github/scripts/agentic-substrate-context/check-agentic-substrate-context.mjs. Edit agentic-substrate-project-state.json, then run with --write. -->
# Agentic Substrate Current Handoff

Canonical source: [\`agentic-substrate-project-state.json\`](./agentic-substrate-project-state.json).

## Repository authority

- Writable repository: **\`${state.authority.authoritativeRepository}\`** via \`${state.authority.writeRemote}\`.
- Default base: \`${state.authority.defaultBaseRef}\`.
- Read-only upstream: **\`${state.authority.readOnlyUpstreamRepository}\`** via \`${state.authority.readOnlyUpstreamRemote}\`.
- GitHub writes are allowed only in \`${state.authority.githubWriteAllowlist.join(', ')}\`.

## Delivery state

- Branch: \`${state.delivery.currentBranch}\`.
- Status: **\`${state.delivery.status}\`**.
- Implemented through: \`${state.delivery.implementedThrough}\`.
- Merged through: \`${state.delivery.mergedThrough}\`.
- Current coordinate: \`${state.delivery.currentCoordinate}\` (\`${state.delivery.currentCoordinateStatus}\`).
- Next coordinate after merge: \`${state.delivery.nextCoordinateAfterMerge}\`.
- Fork pull request: ${state.delivery.forkPullRequest === null ? 'none' : state.delivery.forkPullRequest}.
- Pull request creation requires explicit user approval.

## Last verified evidence

- Verified at: \`${state.verification.lastVerifiedAt}\`.
- Registry: ${state.verification.domainSchemas} schemas; ${state.verification.migrations} migrations / ${state.verification.tables} tables.
- Fingerprint: \`${state.verification.schemaFingerprint}\`.
- Unit: ${state.verification.unitTestFiles} files / ${state.verification.unitTests} tests.
- PostgreSQL: ${state.verification.postgresTestFiles} files / ${state.verification.postgresTests} tests.
${experiments}

## Known residuals

${residuals}

## Next actions

${nextActions}

## New-session bootstrap

1. Read the repository \`AGENTS.md\` chain.
2. Read the canonical JSON and this generated handoff.
3. Run \`node .github/scripts/agentic-substrate-context/check-agentic-substrate-context.mjs --local\`.
4. Reconcile cached memory against Git and GitHub before acting.
`
}

export function renderSerenaProjectContext(state) {
  return `<!-- Generated by .github/scripts/agentic-substrate-context/check-agentic-substrate-context.mjs. Do not edit directly. -->
# Orca Project Context

Always read \`AGENTS.md\`, \`docs/agentic-substrate-project-state.json\`, and \`docs/agentic-substrate-current-handoff.md\` before work.

- Writable repository: \`${state.authority.authoritativeRepository}\` through \`${state.authority.writeRemote}\`.
- \`${state.authority.readOnlyUpstreamRepository}\` is read-only through \`${state.authority.readOnlyUpstreamRemote}\`; never create or mutate GitHub resources there.
- Current branch: \`${state.delivery.currentBranch}\`.
- Delivery: \`${state.delivery.status}\`; implemented through \`${state.delivery.implementedThrough}\`, merged through \`${state.delivery.mergedThrough}\`.
- Run \`node .github/scripts/agentic-substrate-context/check-agentic-substrate-context.mjs --local\` before any external Git or GitHub action.
- Treat this memory as a pointer. The canonical JSON and live Git/GitHub state win on conflict.
`
}
